//! The kiosk reference screens Screen Compiler converts, exactly as it wrote
//! them, each with a function that builds it on a real `nowayos-ui` tree.
//! Generated by tools/screens (`make screens-bless`): do not edit by hand.

use nowayos_ui::{NodeId, Tree, UiError};

/// Nodes a screen may use: more than any converted screen needs.
pub const CAPACITY: usize = 64;

/// Bytes of long text a screen may hold (builder contract v16): more than
/// any converted screen needs.
pub const TEXT: usize = 4096;

/// Builds a screen on a real tree and returns its root node.
pub type Build = fn(&mut Tree<CAPACITY, TEXT>) -> Result<NodeId, UiError>;

/// Every converted screen: its file's name and the function that builds it.
pub const SCREENS: &[(&str, Build)] = &[
    ("attract", build_attract),
    ("gallery-buttons", build_gallery_buttons),
    ("gallery-choices", build_gallery_choices),
    ("gallery-css", build_gallery_css),
    ("gallery-fields", build_gallery_fields),
    ("gallery-icons", build_gallery_icons),
    ("gallery-keyboard", build_gallery_keyboard),
    ("gallery-layout", build_gallery_layout),
    ("gallery-scroll", build_gallery_scroll),
    ("gallery-surfaces", build_gallery_surfaces),
    ("gallery-text", build_gallery_text),
    ("gallery-type", build_gallery_type),
    ("launcher", build_launcher),
    ("pump-bar", build_pump_bar),
    ("service-desk-bar", build_service_desk_bar),
    ("visitor-bar", build_visitor_bar),
    ("why-secure", build_why_secure),
];

/// `attract.tsx`, converted by Screen Compiler.
pub mod attract {
    include!("attract.rs");
}

/// Builds `attract.tsx`'s screen `attract_screen` on a real tree.
///
/// # Errors
///
/// The tree's error, if the screen does not fit it.
pub fn build_attract(tree: &mut Tree<CAPACITY, TEXT>) -> Result<NodeId, UiError> {
    attract::attract_screen::build(tree).map(|nodes| nodes.root)
}

